(function () { const DAILY_KEYWORD_POOL = [ ["Generative AI", "Future Tech", "Custom LLM"], ["Cloud Native", "Kubernetes", "AWS Migration"], ["Digital Transformation", "Enterprise UX", "Product Strategy"], ["WhatsApp API", "Chatbot Automation", "Customer Engagement"], ["SaaS Development", "MVP Builder", "Startup Tech Partner"], ["Cybersecurity", "GDPR Compliance", "Data Protection"], ["DevOps", "CI/CD Pipelines", "Site Reliability"], ["React Native", "Cross-Platform Mobile", "Progressive Web Apps"], ["API Integration", "Business Automation", "Microservices"], ["Machine Learning", "Data Analytics", "Predictive Modeling"], ]; function updateKeywords() { const metaKeywords = document.querySelector('meta[name="keywords"]'); if (!metaKeywords) return; const currentKeywords = metaKeywords.getAttribute("content") || ""; const today = new Date(); const dayOfYear = Math.floor( (today - new Date(today.getFullYear(), 0, 0)) / (1000 * 60 * 60 * 24), ); const index = dayOfYear % DAILY_KEYWORD_POOL.length; const dailyTrending = DAILY_KEYWORD_POOL[index].join(", "); if (!currentKeywords.includes(dailyTrending)) { const newKeywords = `${dailyTrending}, ${currentKeywords}`; metaKeywords.setAttribute("content", newKeywords); } } if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", updateKeywords); } else { updateKeywords(); } })();